contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // try an amount and check general invariant about revert behavior and pot/balance
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // read before-state
        uint pot_before = c.pot();
        uint bank_before_balance = address(c).balance; // includes pot_before

        bool reverted;
        // perform the state-changing call
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint pot_after = c.pot();
        uint bank_after_balance = address(c).balance;

        // general rule:
        // - if amount != TICKET_AMOUNT then call must revert and pot unchanged
        // - if amount == TICKET_AMOUNT then either it reverted or:
        //    * pot increased by TICKET_AMOUNT (no payout happened), or
        //    * pot became 0 (payout happened) and contract balance decreased by (pot_before + amount - FEE_AMOUNT) relative to before
        // Expressed without underflows and only using public getters/addresses.
        uint T = C(address(c)).TICKET_AMOUNT();
        uint F = C(address(c)).FEE_AMOUNT();

        if (amount != T) {
            assert(reverted && pot_after == pot_before);
        } else {
            // amount == T
            // either reverted and pot unchanged
            // or not reverted and one of two allowed transitions
            if (reverted) {
                assert(pot_after == pot_before);
            } else {
                // not reverted: either pot increased by T, or pot reset to 0 with correct balance decrease
                bool case_increase = (pot_after == pot_before + T);
                bool case_payout = (pot_after == 0 && bank_after_balance + (pot_before + T - F) == bank_before_balance);
                // The balance arithmetic: when payout occurs, contract's balance should decrease by (pot_before + T - F)
                // Ensure one of the cases holds
                assert(case_increase || case_payout);
            }
        }
    }

    receive() external payable {}
}

