    C c;
    constructor(C _c) { c = _c; }

    // single public test: try calling play forwarding `amount`
    function run(uint amount) public payable {
        // allow any amount; ensure this contract has enough balance to forward it
        require(address(this).balance >= amount);

        // observe public before-state
        uint pot_before = c.pot();
        uint bal_before = address(c).balance;
        address bank_addr = c.bank();

        // call play and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-state
        uint pot_after = c.pot();
        uint bal_after = address(c).balance;

        uint T = 10;
        uint F = 1;

        // General invariant:
        // - If call reverts or amount != T, pot must be unchanged.
        // - If amount == T and call did not revert, then either pot increased by T (no payout),
        //   or pot becomes 0 (payout happened). In the payout case, the contract's balance
        //   must have decreased by some value between (pot_before + T - F) and (pot_before + T)
        //   inclusive (i.e., the bank gets at least the fee F and at most whole pot_before+T).
        assert(
            // reverted or wrong amount => pot unchanged
            ((reverted || amount != T) && pot_after == pot_before)
            ||
            // succeeded with correct amount => pot either increased by T or reset to 0
            (!reverted && amount == T && (
                pot_after == pot_before + T
                || (
                    pot_after == 0
                    // in payout case, balance decrease d = bal_before - bal_after
                    && bal_before >= bal_after
                    && (bal_before - bal_after) <= (pot_before + T)
                    && (bal_before - bal_after) >= (pot_before + T - F)
                )
            ))
        );
    }

    // allow this test contract to receive ETH for forwarding
    receive() external payable {}
}

