        require(address(this).balance >= amount);

        // read observable before-state
        address beforeBank = c.bank();
        uint beforePot = c.pot();
        uint beforeBalanceC = address(c).balance;

        bool reverted;
        // call play with provided amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable after-state
        address afterBank = c.bank();
        uint afterPot = c.pot();
        uint afterBalanceC = address(c).balance;

        // General rule asserted for all inputs:
        // - bank must not change
        // - if call reverted: no state-change must have occurred (pot and contract balance unchanged)
        // - if call did not revert: then either pot increased exactly by C.TICKET_AMOUNT (and contract balance increased by same amount),
