        // We express the payout case as: afterPot == 0 and afterBalanceC <= beforeBalanceC + amount
        // (we avoid reasoning about exact payout amount since transfers go to external addresses).

        assert(
            afterBank == beforeBank
            && (
                reverted
                ? (afterPot == beforePot && afterBalanceC == beforeBalanceC)
                : (
                    (afterPot == beforePot + c.TICKET_AMOUNT() && afterBalanceC == beforeBalanceC + c.TICKET_AMOUNT())
                    || (afterPot == 0 && afterBalanceC <= beforeBalanceC + amount)
                )
            )
        );
    }

